"""Render a standalone audit report, outside the application."""
from pathlib import Path
import json,html,re
P=Path(__file__).resolve().parent
R=json.loads((P/'results.json').read_text(encoding='utf-8'))
A=json.loads((P/'arbitrages.json').read_text(encoding='utf-8'))
E=html.escape
NAMES=dict(erpnext='ERPNext / Frappe',odoo='Odoo Community',tryton='Tryton / Sao',axelor='Axelor / Platform / Studio')
IDS=list(NAMES)
def n(v,d=2):return f'{v:,.{d}f}'.replace(',',' ').replace('.',',')
def prose(text):return '. '.join(part[:1].upper()+part[1:] for part in re.split(r'\s*;\s*',text))
def link(path):return '<a href="../../'+E(path,quote=True)+'">'+E(path)+'</a>'
def table(headers,rows,caption):
 return '<div class="scroll" tabindex="0" role="region" aria-label="'+E(caption)+'"><table><caption>'+E(caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+E(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+cell+('</th>' if i==0 else '</td>') for i,cell in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
units={u['id']:u for u in R['units']}
assert set(units)=={u['id'] for u in A['units']} and len(units)==11
rows=[];decisions=[]
for a in A['units']:
 u=units[a['id']];v={x['id']:x for x in u['comparisons']}
 name='<a href="#'+a['id']+'">'+E(u['label'])+'</a>'
 rows.append([name,*[n(v[p]['jh']) for p in IDS],'<strong>'+n(u['adopted_jh'],0)+'</strong>'])
 decisions.append([name,E(a['decision']),E(a['reason'])])
body='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Arbitrage des références OSS — 1er novembre 2026</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f7f6;color:#142d3b;font:15px/1.65 system-ui,sans-serif}main{max-width:1440px;padding:32px;margin:auto}h1{font-size:34px;line-height:1.2;margin:10px 0 18px}h2{font-size:24px;line-height:1.3;margin:36px 0 16px}h3{font-size:19px;margin:18px 0 10px}h4{font-size:16px;margin:0 0 8px}a{color:#14665b}p{max-width:105ch}header,article,.panel{background:white;border:1px solid #d7e1dc;border-radius:12px;padding:24px;margin:18px 0}.badge{display:inline-block;background:#deeee6;padding:5px 12px;border-radius:6px;font-weight:700;color:#194e44}.metrics{display:flex;gap:16px;flex-wrap:wrap;margin:20px 0}.metrics>div{flex:1;min-width:160px;background:#eef6f2;padding:16px;border-radius:8px}.metrics strong{display:block;font-size:27px}.scroll{overflow:auto;max-width:100%;background:white;border:1px solid #d7e1dc;border-radius:8px}.scroll:focus{outline:2px solid #236159}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;vertical-align:top;padding:12px;border-bottom:1px solid #d7e1dc}thead{background:#236159;color:white}tbody th{min-width:220px;width:25%}caption{padding:12px;text-align:left;font-size:16px;font-weight:700}nav{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.refs{overflow-wrap:anywhere;font-size:12px}.product-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.product-grid>section{background:#f0f6f3;padding:16px;border-radius:8px}.compact{font-size:13px}.section-label{font-weight:700;color:#236159}li+li{margin-top:6px}code{overflow-wrap:anywhere;font-size:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-width:100%}.decision{font-weight:700;font-size:19px;color:#194e44}.top{float:right;font-size:13px}@media(max-width:700px){main{padding:12px}h1{font-size:26px}header,article,.panel{padding:18px}.product-grid{grid-template-columns:1fr}.metrics{gap:8px}.metrics>div{min-width:140px}th,td{padding:10px}tbody th{min-width:180px}}@media print{body{background:white}main{padding:0}nav{display:none}.scroll{overflow:visible}table{font-size:10px}a{color:inherit}}
</style><main id="top"><header><span class="badge">Audit · Propositions non adoptées</span><h1>Choisir les références OSS pour chaque lot</h1><p>1er novembre 2026. Les arbitrages ci-dessous sont proposés pour la prochaine estimation. Les onze montants adoptés et l’application restent inchangés.</p><div class="metrics"><div><strong>11</strong>lots audités</div><div><strong>44</strong>estimations reproduites</div><div><strong>88</strong>capacités rattachées aux lots</div><div><strong>6 660 JH</strong>total adopté conservé</div></div><p><strong>Axelor reste une référence pertinente de construction Java et React sur plusieurs responsabilités. Le choix systématique du même ERP pour un lot entier doit céder la place à un choix explicite des composants comparables.</strong></p><nav><a href="#arbitrages">Arbitrages</a><a href="#estimations">Estimations</a><a href="#divergences">Divergences décisives</a><a href="#protocole">Prochaine proposition</a><a href="#preuves">Preuves</a></nav></header>'''
body+='<section id="arbitrages"><h2>Arbitrage proposé pour chaque lot</h2><p>Les critères sont appliqués dans cet ordre : même responsabilité fonctionnelle, complétude de la mesure, réutilisation et financement, puis adéquation Java/React. Un montant plus faible, plus proche ou plus médian ne constitue pas un motif de sélection.</p>'+table(['Fonction / lot','Arbitrage recommandé','Justification'],decisions,'Décisions proposées')+'</section>'
body+='<section id="estimations"><h2>Les quatre résultats actuels</h2><p>JH de construction Flow, compléments compris. Les résultats OSS sont présentés avant arrondi. Le moteur courant les reproduit, sans nouvelle calibration.</p>'+table(['Fonction / lot',*[NAMES[p] for p in IDS],'Adopté · JH'],rows,'Estimations reproduites en JH')+'</section>'
body+='''<section id="divergences"><h2>Ce qui explique les écarts</h2><article><h3>Ateliers visuels : un rapport de 24,88 entre les résultats</h3><p>De 33,61 à 836,08 JH. Le panier contient 1 fichier calendrier Tryton, 7 fichiers Frappe, 14 fichiers Axelor et 56 fichiers Odoo de calendrier, kanban et aides de vue. Les tailles nettes sont respectivement 200, 1 061, 837,515 et 3 717,88 unités logiques. Ces nombres ne désignent pas des lignes physiques de code.</p><p><strong>Arbitrage :</strong> cadre React Axelor comme ancre, Frappe comme contrepoint. Recompléter Tryton ou l’écarter comme ancre. Réduire Odoo au même périmètre, puis mesurer les trois ateliers métier Flow et leurs interactions.</p></article><article><h3>Master Plan : une banque différente amplifiée par le même multiplicateur</h3><p>Trois modules nouveaux à 0,6 analogue et quatre à 0,65 analogue utilisent la même banque de calcul net par produit. La partie correspondante vaut 4,4 fois cette banque, avant modèles et structures. Ce ne sont pas sept modules Flow observés.</p>'''
planning=units['master-plan-java-spring']
body+=table(['Référence','Banque nette · unités logiques','Taille Master Plan','Taille préparation des plans'],[[E(NAMES[p]),n(planning['families']['master-plan'][p]['analogue'],0),n(planning['families']['master-plan'][p]['total']),n(planning['families']['plan-preparation'][p]['total'])] for p in IDS],'Décomposition de la taille du Master Plan')
body+='''<p>ERPNext représente des plans de production et demandes matière. Odoo représente un centre de charge. Tryton mesure ventes et approvisionnement. Axelor mesure une chaîne MRP. Le résultat Odoo bas ne représente donc pas un Master Plan identique.</p><p><strong>Arbitrage :</strong> Axelor pour le calcul net Java, ERPNext pour compléter la lecture des contributions et besoins après exclusion de la fabrication hors périmètre, Tryton comme contrepoint. Écarter le panier Odoo actuel comme ancre globale.</p></article><article><h3>Process Management : 88 à 91 % de la taille préparée est commune</h3><p>Le studio Axelor apporte 9 734 unités après fraction 0,5. Les formulaires Axelor apportent 6 370,3775 unités après fraction 0,5. Le graphe/pivot Odoo apporte 1 268,25 unités après fraction 0,75. Les mêmes 17 372,6275 unités sont utilisées dans les quatre lectures. Elles représentent 87,7 à 90,9 % de leur taille préparée.</p><p>La banque Studio inclut <code>react/bpm/bundled-config.js</code>, mesuré à 897 unités. Il embarque un assemblage de règles BPMN. Il faut en séparer bibliothèque fournie et adaptation spécifique dans une future banque. Les preuves actuelles restent figées.</p><p><strong>Arbitrage :</strong> conserver le composite Axelor studio/formulaires et Odoo analytique. Isoler les bibliothèques graphiques et moteurs réutilisés, puis les adaptateurs Temporal et la couche Flow.</p></article><article><h3>Propriété : des analogues Stock, pas quatre registres de propriété</h3><p>Les banques de réservation sont de 178,05 unités ERPNext, 324,15 Odoo, 346 Tryton et 91 Axelor. Les banques de correction sont de 611,7, 528,3, 420,8 et 281,8 unités. Les six modules nouveaux de propriété sont extrapolés de ces mécanismes. La plus petite banque ne départage pas les règles de transfert, preuves et lectures aux deux dates.</p><p><strong>Arbitrage :</strong> garder Axelor pour la transposition Java, et dimensionner les responsabilités propres du registre et des actes Flow à partir d’analogues explicitement choisis.</p></article><article><h3>Prestations : le total cache des compensations</h3><p>Le rapport maximum/minimum global est de 1,22, mais les familles divergent dans des sens opposés. Les tailles ci-dessous appartiennent au même lot et ne sont pas des chiffrages indépendants.</p>'''
services=units['service-fulfilment-java-spring']
body+=table(['Famille',*[NAMES[p] for p in IDS]],[[E(f),*[n(parts[p]['total']) for p in IDS]] for f,parts in services['families'].items()],'Tailles préparées par famille de prestation')
body+='''<p><strong>Arbitrage :</strong> choisir les analogues par famille. Les pièces du dossier douanier ne constituent pas un moteur réglementaire. Une demande ou reconnaissance financière n’embarque pas toute la comptabilité.</p></article><article><h3>IT : remettre les noyaux fournis à leur place</h3><p>Axelor contient notamment <code>MFAService.java</code>, des services LDAP, <code>ViewLoader.java</code> et <code>XMLViews.java</code>. Odoo inclut <code>clickbot.js</code>. Frappe et Tryton mesurent encore d’autres périmètres de jobs, imports, messages et traduction. Les crédits Master Data sont déjà déduits, mais les fractions s’appliquent à des banques différentes.</p><p><strong>Arbitrage :</strong> refaire trois paniers : administration/habilitations, opérations/cycle de vie, services de données. Isoler les noyaux Keycloak, Spring, base et outillage fournis, et les adaptations Flow. Aucun ajout ou retrait de budget n’est déduit automatiquement de cette observation.</p></article></section>'''
for a in A['units']:
 u=units[a['id']]
 body+='<article class="unit" id="'+a['id']+'"><a class="top" href="#top">Retour en tête</a><p class="section-label">Arbitrage détaillé</p><h2>'+E(u['label'])+'</h2><p class="decision">'+E(a['decision'])+'</p><p>'+E(a['reason'])+'</p><p class="compact">Décision active conservée : <strong>'+n(u['adopted_jh'],0)+' JH</strong>. Référence actuelle : Axelor. Pas d’arrondi : '+n(u['rounding_jh'],0)+' JH.</p><div class="product-grid">'+''.join('<section><h4>'+E(NAMES[k])+'</h4><p>'+E(a['alternatives'][k])+'</p></section>' for k in IDS)+'</div><h3>Travaux nécessaires à la prochaine estimation</h3><ul>'+''.join('<li>'+E(t)+'</li>' for t in a['next_actions'])+'</ul><h3>Preuves de l’étude</h3><ul class="refs">'+''.join('<li>'+link(t)+'</li>' for t in a['evidence'])+'</ul>'
 if u.get('families'):
  body+='<h3>Exemples de composants mesurés</h3>'
  for f in u['families']:
   family=R['families'][f];body+='<h4>'+E(family['name'])+'</h4><p>'+E(prose(family['scope']))+'</p><ul class="refs">'
   for prod in IDS:
    for b in family['bindings'][prod][:1]:
     repo=R['professional']['repos'][b['repo']];url='https://github.com/'+repo['repository']+'/blob/'+repo['commit']+'/'+b['path']
     body+='<li>'+E(NAMES[prod])+' : <a href="'+E(url,quote=True)+'">'+E(b['path'])+'</a> · '+str(b['atoms'])+' atomes sélectionnés · SHA-256 <code>'+b['sha256']+'</code></li>'
   body+='</ul>'
 body+='</article>'
body+='''<section id="protocole" class="panel"><h2>Protocole pour la prochaine proposition</h2><ol><li>Fixer les mêmes fonctions, exclusions et situations d’acceptation depuis les capacités natives et fonctions professionnelles.</li><li>Choisir pour chaque responsabilité la référence principale, les compléments utiles et les paniers écartés parce que partiels ou trop larges.</li><li>Isoler code métier, bibliothèques et framework fournis, puis patrimoine déjà financé. Chaque mécanisme partagé conserve un propriétaire de financement.</li><li>Préparer une taille dans une convention Java/React homogène. Les instructions Java, Python, JavaScript et XML ne sont pas des observations de productivité comparables par leur seule valeur.</li><li>Sommer les tailles des composants liés, puis appliquer une seule fois COCOMO au lot cohérent. Conserver COSMIC comme autre lecture des fonctions. Ne pas moyenner les quatre JH ni additionner les délais locaux.</li><li>Présenter un candidat distinct des décisions actives, avec ses effets sur les rôles, financements et budgets. Le présent audit ne change aucun montant.</li></ol></section>'''
body+='<section id="preuves" class="panel"><h2>Preuves et reproduction</h2><p>85 preuves de calcul ont été vérifiées par empreinte. Les 1 315 mesures de fichiers professionnels ont été confrontées aux fichiers locaux figés. Les 117 fichiers distincts des analogues métier cohérents ont aussi été vérifiés. Les 369 fichiers protégés du projet sont inchangés après extraction.</p><p>Les documentations éclairent les responsabilités. Les versions et chemins de code figés restent propriétaires des chiffres.</p><ul>'+''.join('<li><a href="'+E(s['url'],quote=True)+'">'+E(s['title'])+'</a>. '+E(s['use'])+'</li>' for s in A['web_sources'])+'</ul><p><a href="results.json">Résultats et décompositions</a> · <a href="arbitrages.json">Arbitrages proposés</a> · <a href="checks.json">Contrôles</a> · <a href="audit.py">Script de reproduction</a></p><pre><code>python audits/2026-11-01-arbitrage-references-oss/audit.py\npython audits/2026-11-01-arbitrage-references-oss/render_report.py</code></pre></section></main></html>'
(P/'rapport.html').write_text(body,encoding='utf-8')
print(json.dumps(dict(report=str(P/'rapport.html'),units=len(A['units']),bytes=len(body.encode())),ensure_ascii=False))
